	"gift_premium_subtitle": "Daj w prezencie roczną subskrypcję %1$s użytkownikowi %2$s za %3$s. Po zakończeniu realizacji płatności odbiorca otrzyma powiadomienie o wysłanym prezencie.",
	"gift_premium_terms_footer": "Opłata w wysokości ceny dawanej w prezencie subskrypcji jest pobierana w chwili zakupu i nie podlega zwrotowi. Ta subskrypcja jest jednorazowa, nie można jej zamienić na inną ani połączyć z inną ofertą, a także nie ma ona wartości pieniężnej. Subskrypcja zostanie aktywowana, gdy zespół serwisu X wykona przegląd i przypisze ją do odbiorcy, który musi potwierdzić nasze %1$s oraz polityki. Jeśli odbiorca nie będzie spełniał wymagań dotyczących uprawnienia do subskrypcji, anuluje subskrypcję albo odrzuci nasze postanowienia i polityki, nie będziesz mieć możliwości ponownego wykorzystania prezentu ani odzyskania jego kosztów. Mogą zostać naliczone odpowiednie podatki. Postanowienia mogą ulec zmianie. %2$s.",
