	"go_to_twitter": "Przejdź na stronę x.com",
	"golive__tip_broadcaster_1": "<b>WSKAZÓWKA:</b> Dziękujemy, że transmitujesz na żywo! Nie zapomnij przywitać swoich widzów, gdy zaczną oglądać transmisję.",
	"golive__tip_broadcaster_10": "<b>WSKAZÓWKA:</b> Dziękujemy za transmisję w serwisie X! ≺3",
	"golive__tip_broadcaster_2": "<b>WSKAZÓWKA:</b> Spróbuj zwracać się do widzów po imieniu, będzie im bardzo miło.",
	"golive__tip_broadcaster_3": "<b>WSKAZÓWKA:</b> Aby mieć pewność, że widzowie Cię odnajdą, transmituj przez co najmniej kilka minut.",
	"golive__tip_broadcaster_4": "<b>WSKAZÓWKA:</b> Jeśli chcesz lepiej poznać swoich widzów, zapytaj ich, skąd pochodzą.",
	"golive__tip_broadcaster_5": "<b>WSKAZÓWKA:</b> Podziękuj swoim widzom za uwagę i odpowiedz na ich komentarze, żeby podtrzymać ich zainteresowanie.",
	"golive__tip_broadcaster_6": "<b>WSKAZÓWKA:</b> Jeśli podczas transmisji na żywo stracisz łączność z siecią, przejdź do miejsca, w którym występuje silniejszy sygnał.",
	"golive__tip_broadcaster_7": "<b>WSKAZÓWKA:</b> Zaproś swoich widzów do obserwowania Twojego konta. Dzięki temu będą zawsze otrzymywać powiadomienia o tym, że transmitujesz.",
	"golive__tip_broadcaster_8": "<b>WSKAZÓWKA:</b> Na początku transmisji na żywo przywitaj swoich widzów. Będzie im miło.",
	"golive__tip_broadcaster_9": "<b>WSKAZÓWKA:</b> Przed zakończeniem transmisji podziękuj swoim widzom za uwagę.",
	"golive__tip_pre_broadcast_1": "<b>WSKAZÓWKA:</b> Dodaj tytuł przed rozpoczęciem transmisji i przyciągnij użytkowników o podobnych zainteresowaniach!",
	"golive__tip_pre_broadcast_2": "<b>WSKAZÓWKA:</b> Opisowy tytuł informuje użytkowników o tematyce transmisji.",
	"golive__tip_pre_broadcast_3": "<b>WSKAZÓWKA:</b> Szukasz pomysłów? Zorganizuj wycieczkę, pochwal się swoją twórczością lub opowiedz coś na temat, który Cię interesuje.",
	"golive__tip_pre_broadcast_4": "<b>WSKAZÓWKA:</b> Przed rozpoczęciem transmisji upewnij się, że siła sygnału jest dostatecznie dobra.",
	"golive__tip_pre_broadcast_5": "<b>WSKAZÓWKA:</b> Odpowiednio otaguj tytuł, aby użytkownicy Twittera mogli łatwo odnaleźć Twoją transmisję.",
	"golive__tip_pre_broadcast_6": "<b>WSKAZÓWKA:</b> To już wszystkie wskazówki. Dziękujemy za transmisję w serwisie X!",
