	"identity_description": "Zweryfikuj dokument tożsamości wydany przez organ państwowy, aby potwierdzić swoją tożsamość i odblokować funkcje dostępne dla subskrybentów usługi Premium.",
	"identity_education_camera_permissions": "Aby zweryfikować Twoją tożsamość, musimy uzyskać dostęp do aparatu Twojego urządzenia",
	"identity_education_cancel": "Na razie pomiń",
	"identity_education_conditions": "Wyrażam zgodę na używanie przez firmy X i Au10tix obrazów przedstawiających mój dokument tożsamości oraz moją twarz, w tym wyodrębnionych z nich danych biometrycznych, w celu potwierdzenia mojej tożsamości, a także na potrzeby zapewnienia bezpieczeństwa i zabezpieczeń w serwisie X, w tym w celu zapobiegania naśladownictwu. Firma Au10tix może przechowywać takie dane nie dłużej niż przez 30 dni. {{}}Dowiedz się więcej{{}}.",
	"identity_education_conditions_age_verification": "Wyrażam zgodę na używanie przez firmy X i Persona obrazów przedstawiających mój dokument tożsamości oraz moje zdjęcie w celu potwierdzenia mojego wieku. Twoje zdjęcie nie będzie przechowywane. X i xAI mogą zachować informacje dotyczące Twojego wieku. {{}}Dowiedz się więcej{{}}.",
	"identity_education_conditions_eea": "\"Wyrażam zgodę na udostępnianie przez firmę X zdjęć mojego dokumentu tożsamości, w tym danych biometrycznych, oraz danych osobowych z mojego profilu firmie Au10tix w celu potwierdzenia mojej tożsamości.\nWyrażam również zgodę na przechowywanie przez firmę X zdjęć mojego dokumentu tożsamości, w tym danych biometrycznych, przez maksymalnie 30 dni, a także używanie ich oraz danych z mojego profilu do celów związanych z bezpieczeństwem i zabezpieczeniami, w tym w celu zapobiegania naśladownictwu. {{}}Dowiedz się więcej{{}}.\"",
	"identity_education_conditions_persona_vendor": "Wyrażam zgodę na używanie przez firmy X i Persona obrazów przedstawiających mój dokument tożsamości oraz moją twarz, w tym wyodrębnionych z nich danych biometrycznych, w celu potwierdzenia mojej tożsamości, a także na potrzeby zapewnienia bezpieczeństwa i zabezpieczeń w serwisie X, zapobiegania oszustwom i obsługi płatności. Firma Persona może przechowywać takie dane nie dłużej niż przez 30 dni. Firma X może przechowywać moje imię i nazwisko, adres oraz wartości skrótów mojego dokumentu tożsamości, dopóki będę subskrybować usługę X Premium. {{}}Dowiedz się więcej{{}}.",
