	"ps__tip_broadcaster_1": "<b>WSKAZÓWKA:</b> Dziękujemy za transmisję! Nie zapomnij przywitać swoich widzów, gdy zaczną oglądać transmisję.",
	"ps__tip_broadcaster_11": "<b>WSKAZÓWKA:</b> Dziękujemy za transmisję w Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>WSKAZÓWKA:</b> Spróbuj zwracać się do widzów po imieniu, będzie im bardzo miło.",
	"ps__tip_broadcaster_3": "<b>WSKAZÓWKA:</b> Aby mieć pewność, że widzowie Cię odnajdą, transmituj przez co najmniej kilka minut.",
	"ps__tip_broadcaster_4": "<b>WSKAZÓWKA:</b> Jeśli chcesz lepiej poznać swoich widzów, zapytaj ich skąd pochodzą.",
	"ps__tip_broadcaster_5": "<b>WSKAZÓWKA:</b> Podziękuj swoim widzom za uwagę i odpowiedz na ich komentarze, żeby podtrzymać ich zaangażowanie.",
	"ps__tip_broadcaster_6": "<b>WSKAZÓWKA:</b> Jeśli podczas transmisji stracisz łączność z siecią, przejdź do miejsca, w którym występuje silniejszy sygnał.",
	"ps__tip_broadcaster_7": "<b>WSKAZÓWKA:</b> Zaproś swoich widzów do obserwowania Twojego konta. Dzięki temu będą zawsze otrzymywać powiadomienia o tym, że transmitujesz.",
	"ps__tip_broadcaster_8": "<b>WSKAZÓWKA:</b> Na początku transmisji przywitaj swoich widzów. Będzie im miło.",
	"ps__tip_broadcaster_9": "<b>WSKAZÓWKA:</b> Przed zakończeniem transmisji podziękuj swoim widzom za uwagę.",
	"ps__tip_pre_broadcast_1": "<b>WSKAZÓWKA:</b> Dodaj tytuł przed rozpoczęciem transmisji i przyciągnij użytkowników o podobnych zainteresowaniach!",
	"ps__tip_pre_broadcast_2": "<b>WSKAZÓWKA:</b> Opisowy tytuł informuje użytkowników o tematyce transmisji.",
	"ps__tip_pre_broadcast_3": "<b>WSKAZÓWKA:</b> Szukasz pomysłów? Zorganizuj wycieczkę, pochwal się swoją twórczością lub opowiedz coś na temat, który Cię interesuje.",
	"ps__tip_pre_broadcast_4": "<b>WSKAZÓWKA:</b> Przed rozpoczęciem transmisji upewnij się, że siła sygnału jest dostatecznie dobra.",
	"ps__tip_pre_broadcast_5": "<b>WSKAZÓWKA:</b> udostępnij swoje transmisje w serwisie X, aby zdobyć więcej widzów.",
	"ps__tip_pre_broadcast_6": "<b>WSKAZÓWKA:</b> Osoby, które wzajemnie się obserwują, mogą udostępniać między sobą transmisje prywatne.",
	"ps__tip_pre_broadcast_8": "<b>WSKAZÓWKA:</b> Odpowiednio otaguj tytuł, aby użytkownicy mogli łatwo odnaleźć Twoją transmisję.",
	"ps__tip_pre_broadcast_9": "<b>WSKAZÓWKA:</b> To już wszystkie wskazówki. Dziękujemy za korzystanie z Periscope!",
	"ps__tip_viewer_1": "<b>WSKAZÓWKA:</b> Jesteś jedną z pierwszych osób. Napisz coś, żeby się przywitać!",
	"ps__tip_viewer_2": "<b>WSKAZÓWKA:</b> Dodaj komentarz, żeby <b>%1$s</b> wiedział/a, że tu jesteś!",
	"ps__tip_viewer_3": "<b>WSKAZÓWKA:</b> Niech <b>%1$s</b> dowie się, skąd oglądasz!",
	"ps__tip_viewer_4": "<b>WSKAZÓWKA:</b> Dołącz do czatu wraz z <b>%1$s</b> i innymi oglądającymi.",
